import org.springframework.context.annotation.*;
import org.springframework.stereotype.*;

// 依存される側(部品):インターフェースと実装
interface MailSender {
    String send(String to, String body);
}

@Component
class LogMailSender implements MailSender {
    public String send(String to, String body) {
        return "[LOG] " + to + " へ送信: " + body;
    }
}

// 依存する側:部品はコンストラクタで受け取る(1つなら @Autowired 不要)
@Service
class OrderService {
    private final MailSender mail;

    OrderService(MailSender mail) {
        this.mail = mail;
        System.out.println("OrderService を new した(部品: "
                + mail.getClass().getSimpleName() + ")");
    }

    void placeOrder(String user, String item) {
        System.out.println(mail.send(user, item + " のご注文を承りました"));
    }
}

System.out.println("--- ① 手動で組み立て(素の Java の DI)---");
var manual = new OrderService(new LogMailSender());
manual.placeOrder("haru@example.com", "コーヒー豆");

System.out.println("--- ② IoC コンテナに組み立てを任せる ---");
// ここを変えてみよう:LogMailSender.class を消して実行すると?(部品が無くて起動失敗)
var ctx = new AnnotationConfigApplicationContext(
        LogMailSender.class, OrderService.class);
OrderService s = ctx.getBean(OrderService.class);
s.placeOrder("moka@example.com", "ドリップバッグ");
System.out.println("もう一度 getBean しても同じもの? "
        + (s == ctx.getBean(OrderService.class)));
ctx.close();

import org.springframework.beans.factory.annotation.*;
import org.springframework.context.annotation.*;
import org.springframework.stereotype.*;

interface Notifier {
    String send(String message);
}

// ライブラリのクラスのつもり(アノテーションは付いていない)
class MailNotifier implements Notifier {
    private final String from;
    MailNotifier(String from) { this.from = from; }
    public String send(String m) { return "メール(" + from + "): " + m; }
}

class SlackNotifier implements Notifier {
    private final String channel;
    SlackNotifier(String channel) { this.channel = channel; }
    public String send(String m) { return "Slack(" + channel + "): " + m; }
}

// @Bean メソッドの戻り値が Bean になる。Bean 名はメソッド名
@Configuration
class NotifyConfig {
    @Bean
    @Primary  // ここを変えてみよう:@Primary を消すと起動時にエラー
    Notifier mailNotifier() {
        return new MailNotifier("noreply@example.com");
    }

    @Bean
    Notifier slackNotifier() {
        return new SlackNotifier("#alert");
    }
}

@Service
class ReportService {  // 特に指定なし → @Primary が選ばれる
    private final Notifier notifier;
    ReportService(Notifier notifier) { this.notifier = notifier; }
    void send() { System.out.println(notifier.send("月次レポートです")); }
}

@Service
class AlertService {   // 名前で指定 → @Primary より優先
    private final Notifier notifier;
    // ここを変えてみよう:"slackNotifier" を "mailNotifier" に
    AlertService(@Qualifier("slackNotifier") Notifier notifier) {
        this.notifier = notifier;
    }
    void send() { System.out.println(notifier.send("CPU 使用率 95%!")); }
}

var ctx = new AnnotationConfigApplicationContext(
        NotifyConfig.class, ReportService.class, AlertService.class);
ctx.getBean(ReportService.class).send();
ctx.getBean(AlertService.class).send();
System.out.println("Notifier の Bean: "
        + ctx.getBeansOfType(Notifier.class).keySet());
ctx.close();

import org.springframework.context.annotation.*;
import org.springframework.stereotype.*;

// ダメな例:Bean のフィールドに「ユーザーごとの状態」を持っている
@Service
class BadCartService {
    private int total;  // 全員で共有される!

    int add(String user, int price) {
        total += price;
        return total;
    }
}

// 良い例:状態は持たず、引数で受け取って結果を返す(ステートレス)
@Service
class GoodCartService {
    int add(int currentTotal, int price) {
        return currentTotal + price;
    }
}

// ここを変えてみよう:BadCartService の上に @Scope("prototype") を付けると?
var ctx = new AnnotationConfigApplicationContext(
        BadCartService.class, GoodCartService.class);

// 別々のユーザーのつもりで、それぞれ getBean する
BadCartService forHaru = ctx.getBean(BadCartService.class);
BadCartService forMoka = ctx.getBean(BadCartService.class);
System.out.println("同じインスタンス? " + (forHaru == forMoka));
System.out.println("ハル: 1000円の本 → 合計 " + forHaru.add("haru", 1000));
System.out.println("モカ:  500円の豆 → 合計 " + forMoka.add("moka", 500));
System.out.println("ハル: 200円のペン → 合計 " + forHaru.add("haru", 200));

GoodCartService good = ctx.getBean(GoodCartService.class);
int haruTotal = good.add(0, 1000);   // 状態は呼び出し側(本物ならセッションやDB)
int mokaTotal = good.add(0, 500);
haruTotal = good.add(haruTotal, 200);
System.out.println("ステートレス版 → ハル " + haruTotal + "円 / モカ " + mokaTotal + "円");
